inputs = ['adja', 'gawaf', 'icdxy', 'ib', 'ec']
outputs = ['adja', 'gawax', 'ukccdyyy', 'ukcckbg', 'ec']

print("Detailed analysis:")
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        print(f"\nIndex {i}: '{inputs[i]}' -> '{outputs[i]}'")
        print(f"  Length: {len(inputs[i])} -> {len(outputs[i])}")

        # Let's see character by character
        min_len = min(len(inputs[i]), len(outputs[i]))
        for j in range(min_len):
            if inputs[i][j] != outputs[i][j]:
                print(f"  Position {j}: '{inputs[i][j]}' -> '{outputs[i][j]}'")

        if len(inputs[i]) != len(outputs[i]):
            if len(inputs[i]) > len(outputs[i]):
                print(f"  Removed characters at end")
            else:
                print(f"  Added characters at end")

